arguments.argument:
repeat(8){instance_create(random(room_width), random(room_height), obj_wtf)}

sprite_set_alpha_from_sprite(spr_fog, spr_fog_mask)

switch(global.fog_graphics)
{
    case 0: fgrid = 25; fscale = 2; break;
    case 1: fgrid = 50; fscale = 4; break;
    default: fgrid = 100; fscale = 8;
}

fwid = ceil(room_width / fgrid) + 1
fhei = ceil(room_height / fgrid) + 1

fog_id=ds_grid_create(fwid, fhei)
ds_grid_clear(fog_id, 1)

dw = ceil(view_wview / fgrid) + 1
dh = ceil(view_hview / fgrid) + 1

surf = surface_create(view_wview, view_hview)
surface_set_target(surf)
draw_clear(0)
surface_reset_target()
